/**
 * Rendu PostgreSQL du schéma déclaré dans `db/schema`.
 *
 * Le schéma MySQL est la source unique : les migrations PostgreSQL sont
 * générées depuis les mêmes objets, sinon les deux bases divergent dès la
 * première colonne ajoutée d'un côté.
 *
 * Différences assumées, à documenter dans chaque migration concernée :
 *
 * - `AUTO_INCREMENT` → `GENERATED BY DEFAULT AS IDENTITY`.
 * - `ENUM(...)` → `TEXT` + `CHECK`, nommé `<table>_<colonne>_check` : PostgreSQL
 *   n'a pas de type ENUM par colonne, et une contrainte se modifie sans ALTER
 *   TYPE sur toutes les tables.
 * - `TINYINT(1)` → `SMALLINT` : le code compare à `0`/`1`, pas à un booléen.
 * - `TIMESTAMP`/`DATETIME` → `TIMESTAMPTZ` : la conversion des données se fait
 *   en UTC (task 11), l'ambiguïté de fuseau disparaît à la source.
 * - `JSON` → `JSONB`.
 * - `ON UPDATE CURRENT_TIMESTAMP` → trigger `touch_updated_at()`.
 * - `BIGINT UNSIGNED` → `BIGINT` : la plage haute change, aucune valeur du
 *   domaine ne s'en approche.
 * - `ENGINE`/`CHARSET`/`COLLATE` n'ont pas d'équivalent et disparaissent.
 */

const IDENTIFIER_PATTERN = /^[a-z][a-z0-9_]*$/;

function q(name) {
  if (!IDENTIFIER_PATTERN.test(String(name))) {
    throw new Error(`Identifiant SQL invalide pour PostgreSQL: ${name}`);
  }
  return `"${name}"`;
}

const SIMPLE_TYPES = [
  [/^bigint(\s+unsigned)?$/i, 'BIGINT'],
  [/^int(\s+unsigned)?$/i, 'INTEGER'],
  [/^(tinyint|smallint)(\(1\))?$/i, 'SMALLINT'],
  [/^varchar\((\d+)\)$/i, (_match, size) => `VARCHAR(${size})`],
  [/^char\((\d+)\)$/i, (_match, size) => `CHAR(${size})`],
  [/^(tinytext|text|mediumtext|longtext)$/i, 'TEXT'],
  [/^json$/i, 'JSONB'],
  [/^(timestamp|datetime)$/i, 'TIMESTAMPTZ'],
  [/^date$/i, 'DATE'],
  [/^decimal\((\d+),\s*(\d+)\)$/i, (_match, precision, scale) => `NUMERIC(${precision}, ${scale})`],
];

function parseEnumMembers(definition) {
  const match = /^ENUM\((.*)\)/i.exec(definition.trim());
  if (!match) throw new Error(`ENUM illisible: ${definition}`);
  const members = match[1].match(/'((?:[^']|'')*)'/g);
  if (!members) throw new Error(`ENUM sans valeurs: ${definition}`);
  return members.map((literal) => literal.slice(1, -1).replace(/''/g, "'"));
}

function mapType(columnType, definition) {
  if (/^enum$/i.test(columnType)) return { type: 'TEXT', enumMembers: parseEnumMembers(definition) };
  for (const [pattern, mapped] of SIMPLE_TYPES) {
    const match = pattern.exec(columnType.trim());
    if (match) return { type: typeof mapped === 'function' ? mapped(...match) : mapped };
  }
  throw new Error(`Type MySQL non couvert par le rendu PostgreSQL: ${columnType}`);
}

function parseDefault(definition) {
  const match = /\bDEFAULT\s+('(?:[^']|'')*'|CURRENT_TIMESTAMP|[A-Za-z0-9_.+-]+)/i.exec(definition);
  if (!match) return null;
  const raw = match[1];
  if (/^CURRENT_TIMESTAMP$/i.test(raw)) return 'now()';
  return raw;
}

function renderPostgresColumn(value) {
  const definition = value.definition;
  const { type, enumMembers } = mapType(value.expected.columnType, definition);
  const parts = [q(value.name), type];

  if (/AUTO_INCREMENT/i.test(definition)) {
    // PostgreSQL exige une colonne d'identité en NOT NULL implicite.
    parts.push('GENERATED BY DEFAULT AS IDENTITY');
  } else {
    const defaultValue = parseDefault(definition);
    if (defaultValue !== null) parts.push(`DEFAULT ${defaultValue}`);
    else if (/DEFAULT\s+NULL/i.test(definition)) parts.push('DEFAULT NULL');
  }

  parts.push(/NOT NULL/i.test(definition) ? 'NOT NULL' : 'NULL');

  return {
    sql: parts.join(' '),
    enumMembers,
    touchesUpdatedAt: /ON UPDATE\s+CURRENT_TIMESTAMP/i.test(definition),
  };
}

function renderEnumConstraint(table, column, members) {
  const list = members.map((member) => `'${member.replace(/'/g, "''")}'`).join(', ');
  return `CONSTRAINT ${q(`${table.name}_${column.name}_check`)} CHECK (${q(column.name)} IN (${list}))`;
}

function renderPostgresCreateTable(table) {
  const definitions = table.columns.map((column) => renderPostgresColumn(column).sql);
  for (const column of table.columns) {
    const rendered = renderPostgresColumn(column);
    if (rendered.enumMembers) definitions.push(renderEnumConstraint(table, column, rendered.enumMembers));
  }
  if (table.primaryKey?.length) {
    definitions.push(`PRIMARY KEY (${table.primaryKey.map(q).join(', ')})`);
  }
  for (const foreignKey of table.foreignKeys) {
    const onDelete = foreignKey.onDelete ? ` ON DELETE ${foreignKey.onDelete}` : '';
    definitions.push(
      `CONSTRAINT ${q(foreignKey.name)} FOREIGN KEY (${foreignKey.columns.map(q).join(', ')}) ` +
        `REFERENCES ${q(foreignKey.referencedTable)} (${foreignKey.referencedColumns.map(q).join(', ')})${onDelete}`,
    );
  }
  return `CREATE TABLE IF NOT EXISTS ${q(table.name)} (\n  ${definitions.join(',\n  ')}\n);`;
}

function renderPostgresIndexes(table) {
  return table.indexes.map((value) => {
    const unique = value.unique ? 'UNIQUE ' : '';
    return `CREATE ${unique}INDEX IF NOT EXISTS ${q(value.name)} ON ${q(table.name)} (${value.columns.map((part) => q(typeof part === 'string' ? part : part.column)).join(', ')});`;
  });
}

function renderTouchTrigger(table, columnName) {
  return [
    `DROP TRIGGER IF EXISTS ${q(`${table.name}_touch_${columnName}`)} ON ${q(table.name)};`,
    `CREATE TRIGGER ${q(`${table.name}_touch_${columnName}`)} BEFORE UPDATE ON ${q(table.name)}`,
    `  FOR EACH ROW EXECUTE FUNCTION touch_updated_at(${q(columnName)});`,
  ].join('\n');
}

const TOUCH_FUNCTION = `CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger AS $$
BEGIN
  -- La ligne complète est repassée dans le record : la fusion jsonb ne
  -- remplace qu'un champ, et jsonb_populate_record reconstruit le NEW typé.
  -- clock_timestamp(), pas now() : now() est figé au début de la transaction,
  -- donc une mise à jour dans la même transaction garderait l'ancienne valeur.
  -- Les imports (task 11) posent app.skip_touch = 'on' : une ligne recopiée
  -- doit conserver son updated_at d'origine, pas celui du transfert.
  IF current_setting('app.skip_touch', true) = 'on' THEN
    RETURN NEW;
  END IF;
  -- MySQL ne remplace la colonne que si l'UPDATE ne l'assigne pas. Sans ce
  -- test, une écriture explicite (accessed_at antidaté, updated_at recopié)
  -- serait écrasée par l'horloge : exactement le contraire du comportement
  -- d'origine.
  IF (to_jsonb(NEW) ->> TG_ARGV[0]) IS NOT DISTINCT FROM (to_jsonb(OLD) ->> TG_ARGV[0]) THEN
    NEW := jsonb_populate_record(NEW, to_jsonb(NEW) || jsonb_build_object(TG_ARGV[0], clock_timestamp()));
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;`;

/**
 * Migration complète d'un groupe : table, index, trigger de mise à jour.
 * @param {object[]} tables tables du groupe, dans l'ordre d'application
 */
function renderPostgresGroup(tables, { withTouchFunction = false } = {}) {
  const statements = [];
  if (withTouchFunction) statements.push(TOUCH_FUNCTION);
  for (const table of tables) {
    statements.push(renderPostgresCreateTable(table));
    statements.push(...renderPostgresIndexes(table));
    for (const column of table.columns) {
      if (/ON UPDATE\s+CURRENT_TIMESTAMP/i.test(column.definition)) {
        statements.push(renderTouchTrigger(table, column.name));
      }
    }
  }
  return statements.join('\n\n');
}

module.exports = {
  TOUCH_FUNCTION,
  renderPostgresColumn,
  renderPostgresCreateTable,
  renderPostgresIndexes,
  renderPostgresGroup,
};
